ALTER TABLE public.profiles ADD COLUMN username text, ADD COLUMN bio text NOT NULL DEFAULT '', ADD COLUMN last_active timestamptz;
CREATE UNIQUE INDEX profiles_username_unique ON public.profiles(lower(username)) WHERE username IS NOT NULL;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_username_format CHECK (username IS NULL OR username ~ '^[a-z0-9_]{3,20}$');
CREATE TABLE public.friendships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL, recipient_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(sender_id <> recipient_id));
CREATE UNIQUE INDEX friendship_pair ON public.friendships(least(sender_id,recipient_id),greatest(sender_id,recipient_id));
GRANT SELECT ON public.friendships TO authenticated; GRANT ALL ON public.friendships TO service_role;
ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY;
CREATE POLICY friendship_parties ON public.friendships FOR SELECT TO authenticated USING(auth.uid() IN(sender_id,recipient_id));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, actor_id uuid, kind text NOT NULL, message text NOT NULL, target text, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_owner_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY notification_owner_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.tv_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, host_id uuid NOT NULL, mode text NOT NULL DEFAULT 'board' CHECK(mode IN ('board','answers')), game text NOT NULL DEFAULT 'quiz', status text NOT NULL DEFAULT 'lobby', state jsonb NOT NULL DEFAULT '{}'::jsonb, version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tv_sessions TO authenticated; GRANT ALL ON public.tv_sessions TO service_role;
ALTER TABLE public.tv_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.tv_participants (session_id uuid NOT NULL REFERENCES public.tv_sessions(id) ON DELETE CASCADE, user_id uuid NOT NULL, nickname text NOT NULL, avatar text NOT NULL DEFAULT 'a1', photo_path text, score integer NOT NULL DEFAULT 0, last_seen timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,user_id));
GRANT SELECT ON public.tv_participants TO authenticated; GRANT ALL ON public.tv_participants TO service_role;
ALTER TABLE public.tv_participants ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.is_tv_member(s uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.tv_sessions WHERE id=s AND host_id=u) OR EXISTS(SELECT 1 FROM public.tv_participants WHERE session_id=s AND user_id=u) $$;
REVOKE ALL ON FUNCTION public.is_tv_member(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_tv_member(uuid,uuid) TO authenticated,service_role;
CREATE POLICY tv_member_read ON public.tv_sessions FOR SELECT TO authenticated USING(public.is_tv_member(id,auth.uid()));
CREATE POLICY tv_players_read ON public.tv_participants FOR SELECT TO authenticated USING(public.is_tv_member(session_id,auth.uid()));
CREATE TABLE public.tv_answers (session_id uuid NOT NULL REFERENCES public.tv_sessions(id) ON DELETE CASCADE, round integer NOT NULL, user_id uuid NOT NULL, answer jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,round,user_id));
GRANT SELECT ON public.tv_answers TO authenticated; GRANT ALL ON public.tv_answers TO service_role;
ALTER TABLE public.tv_answers ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_tv_answer ON public.tv_answers FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.is_tv_member(session_id,auth.uid()));
CREATE TABLE public.game_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL, recipient_id uuid NOT NULL, room_id uuid REFERENCES public.rooms(id) ON DELETE CASCADE, session_id uuid REFERENCES public.tv_sessions(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','declined')), created_at timestamptz NOT NULL DEFAULT now(), CHECK((room_id IS NULL)<>(session_id IS NULL)));
GRANT SELECT ON public.game_invites TO authenticated; GRANT ALL ON public.game_invites TO service_role;
ALTER TABLE public.game_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invite_parties ON public.game_invites FOR SELECT TO authenticated USING(auth.uid() IN(sender_id,recipient_id));
CREATE OR REPLACE FUNCTION public.are_friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.friendships WHERE status='accepted' AND ((sender_id=a AND recipient_id=b) OR(sender_id=b AND recipient_id=a))) $$;
REVOKE ALL ON FUNCTION public.are_friends(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.are_friends(uuid,uuid) TO authenticated,service_role;
CREATE POLICY social_photos_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='photos' AND (public.are_friends(auth.uid(),(storage.foldername(name))[1]::uuid) OR EXISTS(SELECT 1 FROM public.tv_participants p WHERE p.user_id=(storage.foldername(name))[1]::uuid AND public.is_tv_member(p.session_id,auth.uid()))));
CREATE OR REPLACE FUNCTION public.search_players(term text) RETURNS TABLE(id uuid,username text,nickname text,avatar text,bio text,matches integer,wins integer,photo_path text,last_active timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.nickname,p.avatar,p.bio,p.matches,p.wins,CASE WHEN p.id=auth.uid() OR public.are_friends(p.id,auth.uid()) THEN p.photo_path ELSE NULL END,CASE WHEN p.id=auth.uid() OR public.are_friends(p.id,auth.uid()) THEN p.last_active ELSE NULL END FROM public.profiles p WHERE auth.uid() IS NOT NULL AND p.username IS NOT NULL AND (lower(p.username)=lower(replace(term,'@','')) OR p.username ILIKE '%'||left(replace(term,'@',''),40)||'%' OR p.nickname ILIKE '%'||left(term,40)||'%') LIMIT 30 $$;
REVOKE ALL ON FUNCTION public.search_players(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.search_players(text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.register_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,username,nickname) VALUES(NEW.id,CASE WHEN NEW.raw_user_meta_data->>'username' ~ '^[a-z0-9_]{3,20}$' THEN NEW.raw_user_meta_data->>'username' ELSE NULL END,left(coalesce(NEW.raw_user_meta_data->>'nickname',''),20)) ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER foto_play_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.register_profile();
ALTER PUBLICATION supabase_realtime ADD TABLE public.friendships,public.notifications,public.game_invites,public.tv_sessions,public.tv_participants;
CREATE OR REPLACE FUNCTION public.commit_tv_round(s uuid,v integer,new_state jsonb,new_status text,scores jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.tv_sessions SET state=new_state,status=new_status,version=version+1 WHERE id=s AND version=v; IF NOT FOUND THEN RETURN false; END IF; UPDATE public.tv_participants p SET score=p.score+coalesce((scores->>p.user_id::text)::integer,0) WHERE session_id=s; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.commit_tv_round(uuid,integer,jsonb,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.commit_tv_round(uuid,integer,jsonb,text,jsonb) TO service_role;